// test/orderExportHandler.test.ts
test('ADMIN_TOKEN が未設定なら、トークンなしでも 401', async () => {
  const deps = { ...(await setup()), adminToken: undefined };
  const res = await handleOrderExport(deps, { token: undefined, query: october });
  assert.equal(res.status, 401);
});

export interface OrderRepository {
  // 照合バッチ用。元の形に戻す
  findByStatusUpdatedBefore(status: OrderStatus, before: Date): Promise<Order[]>;
  /** from 以上 to 未満に更新された注文を、状態を問わず更新順に返す */
  findUpdatedBetween(from: Date, to: Date): Promise<Order[]>;
}
